            # and also try to unwrap using .func (for functools.partial)
            unwrapped = getattr(call, "__wrapped__", None)
            if unwrapped is not None:
                call = unwrapped
                continue

            unwrapped = getattr(call, "func", None)
            if unwrapped is not None:
                call = unwrapped
