import functools, inspect
def f(): pass
def wrap(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.__wrapped__ = func
    return wrapper

# interleaved: partial(wrap(partial(f)))
p = functools.partial(wrap(functools.partial(f)))

def custom_unwrap(call):
    while True:
        if hasattr(call, "func"):
            call = call.func
            continue
        unwrapped = inspect.unwrap(call)
        if unwrapped is not call:
            call = unwrapped
            continue
        break
    return call

print(f"Custom unwrap: {custom_unwrap(p) is f}")
